const std = @import("std");
const zml = @import("zml");

// Generated by zmlsmith from seed 500030.
test "outer_untagged" {
    const platform = zml.testing.env();
    const allocator = std.testing.allocator;
    const io = std.testing.io;

    const Local = struct {
        fn forward(x1: zml.Tensor) [1]zml.Tensor {
            const x0 = zml.Tensor.zeroes(zml.Shape.init(.{1}, .f16));
            _ = &x0;
            const x2 = x0.outer(x1);
            _ = &x2;
            return .{x2};
        }
    };

    const x1: zml.Tensor = .fromShape(zml.Shape.init(.{4}, .f16));
    var exe = try zml.module.compile(allocator, io, Local.forward, .{x1}, platform, .{});
    defer exe.deinit();

    try zml.testing.expectEqualShapes(zml.Shape.init(.{ 1, 4 }, .f16), exe.output_shapes[0]);

    var b1: zml.Buffer = try .fromBytes(io, platform, x1.shape(), .replicated, &[_]u8{
        0, 0, 0, 0, 0, 0, 0, 0,
    });
    defer b1.deinit();
    var res = try zml.testing.autoCall(allocator, io, &exe, Local.forward, .{b1});
    defer for (&res) |*r| r.deinit();

    {
        const expected_data align(16) = [_]u8{
            0, 0, 0, 0, 0, 0, 0, 0,
        };
        const expected: zml.Slice = .init(zml.Shape.init(.{ 1, 4 }, .f16), @as([]const u8, &expected_data));
        try zml.testing.expectClose(io, expected, res[0], .exact_match);
    }
}
